         dict(w='woman',pos='noun',pt='mulher',ex='She is a woman.',expt='Ela é uma mulher.',note='Plural irregular: **woman → women** (pronuncia-se “wimin”).'),
         dict(w='boy',pos='noun',pt='menino',ex='He is a boy.',expt='Ele é um menino.'),
         dict(w='girl',pos='noun',pt='menina',ex='She is a girl.',expt='Ela é uma menina.'),
